const logoData = "";
const logoPoints = 20000;
const logoAspect = 0.18048469;
const logoWidth = addControl("textWidth", "Weekend Text Width", 315, 1050, 700);
const lift = addControl("textLift", "Wave Lift", 0, 55, 12);
const tempo = addControl("textTempo", "Wave Tempo", 0.2, 2.5, 1.0);
const depth = addControl("textDepth", "Wave Depth", 0, 70, 16);
const t = time * tempo;
const id = i + 1;
const k = (i % logoPoints) * 6;
let c0 = logoData.charCodeAt(k);
let c1 = logoData.charCodeAt(k + 1);
let c2 = logoData.charCodeAt(k + 2);
let c3 = logoData.charCodeAt(k + 3);
let c4 = logoData.charCodeAt(k + 4);
let c5 = logoData.charCodeAt(k + 5);
c0 = c0 > 64 ? c0 - 55 : c0 - 48;
c1 = c1 > 64 ? c1 - 55 : c1 - 48;
c2 = c2 > 64 ? c2 - 55 : c2 - 48;
c3 = c3 > 64 ? c3 - 55 : c3 - 48;
c4 = c4 > 64 ? c4 - 55 : c4 - 48;
c5 = c5 > 64 ? c5 - 55 : c5 - 48;
const qx = c0 * 256 + c1 * 16 + c2;
const qy = c3 * 256 + c4 * 16 + c5;
const lx = (qx / 4095 - 0.5) * logoWidth;
const ly = (0.5 - qy / 4095) * logoWidth * logoAspect;
let h = Math.sin(id * 12.9898) * 43758.5453;
h = h - Math.floor(h);
let h2 = Math.sin(id * 78.233) * 19341.113;
h2 = h2 - Math.floor(h2);
const cyc = t - Math.floor(t / 5.2) * 5.2;
const gate = Math.max(0.0, 1.0 - Math.abs(cyc - 2.6) / 1.15);
const crest = -0.72 + 1.44 * (cyc / 5.2);
const dx = lx / logoWidth - crest;
const band = Math.max(0.0, 1.0 - Math.abs(dx) / 0.18);
const amp = lift * gate * gate * (3.0 - 2.0 * gate) * band * band * (3.0 - 2.0 * band);
const shimmer = Math.sin(t * 5.4 + h * 6.28318530718) * amp * 0.07;
target.set(lx, ly + amp + shimmer, depth * amp / (lift + 1.0) * (0.55 + h2 * 0.45));
color.setHSL(0.105 + h2 * 0.035, 0.24 + amp / (lift + 1.0) * 0.38, 0.86 + amp / (lift + 1.0) * 0.12);
if (i === 0) setInfo("Weekend Text", "Vector target map. Already formed with a soft travelling crest.");